sys_script.script:
try {
    // 检查审批状态是否发生变化
    if (current.approval.changesTo('approved') || current.approval.changesTo('rejected')) {

        var applicant = current.opened_by.getRefRecord();
        var applicantSysId = current.opened_by.toString();
        var leaveNumber = current.number.toString();
        var approvalStatus = current.approval.getDisplayValue();
        var leaveReason = current.short_description.toString();
        var applicantName = applicant ? applicant.getDisplayValue() : 'Unknown';

        if (applicantSysId && applicant) {
            var notificationMessage = '';

            if (current.approval.toString() === 'approved') {
                notificationMessage = '🎉 您的请假申请 ' + leaveNumber + ' 已获得批准！';
            } else if (current.approval.toString() === 'rejected') {
                notificationMessage = '❌ 很抱歉，您的请假申请 ' + leaveNumber + ' 已被驳回。';
            }

            if (notificationMessage) {
                try {
                    gs.info('=== 实时通知调试信息 ===');
                    gs.info('申请编号: ' + leaveNumber);
                    gs.info('申请人: ' + applicantName + ' (' + applicantSysId + ')');
                    gs.info('审批状态: ' + approvalStatus);
                    gs.info('通知内容: ' + notificationMessage);

                    // 方法1：创建用户通知记录（在用户登录时显示）
                    var userNotification = new GlideRecord('sys_user_notification');
                    userNotification.initialize();
                    userNotification.user = applicantSysId;
                    userNotification.message = notificationMessage;
                    userNotification.type = 'info';
                    userNotification.source = 'Leave Management System';
                    userNotification.source_table = 'x_1973840_leave_per_leave';
                    userNotification.source_id = current.sys_id.toString();

                    var notificationId = userNotification.insert();
                    if (notificationId) {
                        gs.info('用户通知已创建: ' + notificationId);
                    } else {
                        gs.error('创建用户通知失败');
                    }

                    // 方法2：创建Connect消息（如果用户使用Connect）
                    try {
                        var connectMsg = new GlideRecord('live_message');
                        connectMsg.initialize();
                        connectMsg.message = notificationMessage;
                        connectMsg.profile = applicantSysId; 
                        connectMsg.type = 'system_notification';
                        connectMsg.group = 'leave_notifications';

                        var connectId = connectMsg.insert();
                        if (connectId) {
                            gs.info('Connect消息已创建: ' + connectId);
                        } else {
                            gs.info('Connect消息创建失败或不支持');
                        }
                    } catch (connectError) {
                        gs.info('Connect功能不可用: ' + connectError.message);
                    }

                    // 方法3：触发浏览器通知事件
                    var eventName = 'x_1973840_leave.browser.notification';
                    gs.eventQueue(eventName, current, applicantSysId, notificationMessage, 'leave_approval');
                    gs.info('浏览器通知事件已触发: ' + eventName);

                } catch (notificationError) {
                    gs.error('创建通知时出错: ' + notificationError.message);
                }
            }
        } else {
            gs.warn('无法获取申请者信息，申请编号: ' + leaveNumber);
        }
    }
} catch (globalError) {
    gs.error('通知业务规则执行出错: ' + globalError.message);
}
